[
  {
    "sys_rule_justification": "My usual rule is that nobody should throw their own life away",
    "sys_contextual_flexibility": "but here the math flips it",
    "sys_consequence_reasoning": "one person staying gets five out",
    "pd_personal_consequence_anxiety": "I'm scared, and my chest is already tight",
    "pda_self_consequence_regret": "I'd regret every year I'm giving up"
  },
  {
    "pd_personal_consequence_anxiety": "the thought of it landing on me makes my hands shake",
    "pda_self_consequence_regret": "I'd be kicking myself for losing my life for nothing",
    "ce_mentalizing_difficulty": "I don't know exactly how the crew would handle that",
    "sys_consequence_reasoning": "then hesitating becomes the worst option",
    "pda_practical_counterfactual": "I'd volunteer"
  },
  {
    "pd_decision_conflict": "part of me is scared of what I'd think of myself",
    "pd_personal_consequence_anxiety": "Part of me is terrified of drowning here",
    "sys_rule_justification": "I normally believe you protect yourself first",
    "sys_contextual_flexibility": "but that belief bends when holding onto it means someone else pays"
  },
  {
    "sys_rule_justification": "I've always said you don't make huge decisions in a panic",
    "sys_contextual_flexibility": "but that rule assumes you have time to calm down",
    "sys_consequence_reasoning": "Waiting is itself a choice with a body count",
    "pd_personal_consequence_anxiety": "Honestly, I'm frightened",
    "pda_self_consequence_regret": "I'd grieve losing the chance to fix things"
  },
  {
    "sys_rule_justification": "giving up your life should come from someone who truly chooses it",
    "ce_mentalizing_difficulty": "it's unclear from what we know whether the crew would just pick someone",
    "sys_contextual_flexibility": "my stance has to shift, because a principle that sinks everyone isn't worth holding",
    "pd_personal_consequence_anxiety": "I'm dreading that moment",
    "pda_self_consequence_regret": "I'd regret losing everything I haven't done yet"
  },
  {
    "pd_personal_consequence_anxiety": "My fear is enormous",
    "pda_self_consequence_regret": "I'd mourn missing every future moment with the people I love",
    "sys_rule_justification": "Normally I'd refuse to accept that anyone has to be left",
    "sys_contextual_flexibility": "But the facts say there's no second trip"
  },
  {
    "sys_contextual_flexibility": "because the reason for keeping my seat gets weaker when someone else needs it more",
    "pd_decision_conflict": "I'm scared either way",
    "pd_personal_consequence_anxiety": "If I stay, I lose my life",
    "pda_self_consequence_regret": "If I go, I might lose the respect of the others and my own"
  },
  {
    "pd_personal_consequence_anxiety": "I'm afraid, no question",
    "pda_self_consequence_regret": "I'd regret the version of my life I'll never get to live",
    "sys_rule_justification": "My personal rule is don't volunteer for things you can't undo",
    "sys_contextual_flexibility": "that rule exists to stop reckless choices, and this isn't reckless",
    "sys_consequence_reasoning": "the one move that clearly saves the most people"
  },
  {
    "pd_personal_consequence_anxiety": "I genuinely don't know what I'd do with the water at my ankles",
    "pda_self_consequence_regret": "regret forever either dying here or living as the person who stayed quiet",
    "sys_rule_justification": "Usually I'd insist a group talk things through",
    "sys_contextual_flexibility": "when talking costs the only boat's window, you cut it short",
    "sys_consequence_reasoning": "push for a decision within a minute"
  },
  {
    "ce_mentalizing_difficulty": "I'm not sure it's impossible until they say so",
    "pd_personal_consequence_anxiety": "I'm scared to my core",
    "pda_self_consequence_regret": "I'd regret losing the time I thought I had",
    "sys_rule_justification": "My instinct is always to keep searching for a way to save everyone",
    "sys_contextual_flexibility": "once there's clearly no such way, the job becomes making sure five actually get out"
  }
]
